import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * 费用计算工具类（纯 Java，无外部依赖）。
 *
 * 规则来源：docs/费用规则.md
 * - 配送费：itemCount=0 返回 0；amount>200 且 itemCount>0 返回 0，否则 12。
 * - 服务费：amount=0 返回 0；0<amount<=100 返回 2；amount>100 返回 5。
 * - 负金额、负件数、null 非法，抛 IllegalArgumentException。
 * - 金额返回值统一保留 2 位小数，不修改输入 BigDecimal。
 */
public final class FeeCalculator {

    /** 配送费默认值（元）。 */
    private static final BigDecimal DELIVERY_FEE_DEFAULT = new BigDecimal("12");

    /** 配送费免收阈值（元），严格大于该值才免收。 */
    private static final BigDecimal DELIVERY_FREE_THRESHOLD = new BigDecimal("200");

    /** 服务费低档金额（元）。 */
    private static final BigDecimal SERVICE_FEE_LOW = new BigDecimal("2");

    /** 服务费高档金额（元）。 */
    private static final BigDecimal SERVICE_FEE_HIGH = new BigDecimal("5");

    /** 服务费分档阈值（元），严格大于该值进入高档。 */
    private static final BigDecimal SERVICE_FEE_THRESHOLD = new BigDecimal("100");

    /** 金额统一保留的小数位数。 */
    private static final int SCALE = 2;

    private FeeCalculator() {
        // 工具类，禁止实例化
    }

    /**
     * 计算配送费。
     *
     * @param amount    订单金额（元），不能为 null，必须 >= 0
     * @param itemCount 商品件数，不能小于 0
     * @return 配送费（元），保留 2 位小数
     * @throws IllegalArgumentException 当 amount 为 null、amount < 0 或 itemCount < 0 时
     */
    public static BigDecimal deliveryFee(BigDecimal amount, int itemCount) {
        // 业务对象一：配送费校验（金额 + 件数）
        if (amount == null) {
            throw new IllegalArgumentException("配送费计算失败：订单金额不能为 null");
        }
        if (amount.compareTo(BigDecimal.ZERO) < 0) {
            throw new IllegalArgumentException("配送费计算失败：订单金额不能为负数，实际为 " + amount);
        }
        if (itemCount < 0) {
            throw new IllegalArgumentException("配送费计算失败：商品件数不能为负数，实际为 " + itemCount);
        }

        // 件数为 0，直接返回 0
        if (itemCount == 0) {
            return scale(BigDecimal.ZERO);
        }

        // 件数 > 0 且金额严格大于 200，免配送费
        if (amount.compareTo(DELIVERY_FREE_THRESHOLD) > 0) {
            return scale(BigDecimal.ZERO);
        }

        // 其余情况（含金额恰好 200）收取默认配送费
        return scale(DELIVERY_FEE_DEFAULT);
    }

    /**
     * 计算服务费。
     *
     * @param amount 订单金额（元），不能为 null，必须 >= 0
     * @return 服务费（元），保留 2 位小数
     * @throws IllegalArgumentException 当 amount 为 null 或 amount < 0 时
     */
    public static BigDecimal serviceFee(BigDecimal amount) {
        // 业务对象二：服务费校验（仅金额，独立于配送费阈值）
        if (amount == null) {
            throw new IllegalArgumentException("服务费计算失败：订单金额不能为 null");
        }
        if (amount.compareTo(BigDecimal.ZERO) < 0) {
            throw new IllegalArgumentException("服务费计算失败：订单金额不能为负数，实际为 " + amount);
        }

        // 金额为 0，返回 0
        if (amount.compareTo(BigDecimal.ZERO) == 0) {
            return scale(BigDecimal.ZERO);
        }

        // 0 < 金额 <= 100，返回 2
        if (amount.compareTo(SERVICE_FEE_THRESHOLD) <= 0) {
            return scale(SERVICE_FEE_LOW);
        }

        // 金额严格大于 100，返回 5
        return scale(SERVICE_FEE_HIGH);
    }

    /**
     * 统一将金额结果保留 2 位小数（HALF_UP），不修改输入对象。
     */
    private static BigDecimal scale(BigDecimal value) {
        return value.setScale(SCALE, RoundingMode.HALF_UP);
    }
}
