import java.math.BigDecimal;

/**
 * FeeCalculator 独立测试类：main + 断言，无测试框架依赖。
 * 覆盖负数、null、0、100、200 及阈值上下相邻金额；配送费额外覆盖件数 0 与 1。
 */
public class FeeCalculatorTest {

    private static int passed = 0;
    private static int failed = 0;

    public static void main(String[] args) {
        // ===== 配送费：正常流程 =====
        // 件数 0，任意合法金额均返回 0
        assertDelivery("delivery itemCount=0 amount=0", "0.00", BigDecimal.ZERO, 0);
        assertDelivery("delivery itemCount=0 amount=200", "0.00", new BigDecimal("200"), 0);
        assertDelivery("delivery itemCount=0 amount=500", "0.00", new BigDecimal("500"), 0);

        // 件数 1，金额 <= 200 收 12
        assertDelivery("delivery itemCount=1 amount=0", "12.00", BigDecimal.ZERO, 1);
        assertDelivery("delivery itemCount=1 amount=100", "12.00", new BigDecimal("100"), 1);
        assertDelivery("delivery itemCount=1 amount=199.99", "12.00", new BigDecimal("199.99"), 1);
        // 金额恰好 200，不满足严格大于，收 12
        assertDelivery("delivery itemCount=1 amount=200", "12.00", new BigDecimal("200"), 1);
        // 金额 200.01，严格大于 200，免配送费
        assertDelivery("delivery itemCount=1 amount=200.01", "0.00", new BigDecimal("200.01"), 1);
        assertDelivery("delivery itemCount=1 amount=500", "0.00", new BigDecimal("500"), 1);

        // 件数 > 1 同样适用
        assertDelivery("delivery itemCount=3 amount=200", "12.00", new BigDecimal("200"), 3);
        assertDelivery("delivery itemCount=3 amount=200.01", "0.00", new BigDecimal("200.01"), 3);

        // ===== 配送费：异常流程 =====
        assertThrows("delivery null amount", () -> FeeCalculator.deliveryFee(null, 1));
        assertThrows("delivery negative amount", () -> FeeCalculator.deliveryFee(new BigDecimal("-0.01"), 1));
        assertThrows("delivery negative itemCount", () -> FeeCalculator.deliveryFee(new BigDecimal("100"), -1));

        // ===== 服务费：正常流程 =====
        assertService("service amount=0", "0.00", BigDecimal.ZERO);
        assertService("service amount=0.01", "2.00", new BigDecimal("0.01"));
        assertService("service amount=50", "2.00", new BigDecimal("50"));
        // 金额恰好 100，属于 (0,100] 区间，返回 2
        assertService("service amount=100", "2.00", new BigDecimal("100"));
        // 金额 100.01，严格大于 100，返回 5
        assertService("service amount=100.01", "5.00", new BigDecimal("100.01"));
        assertService("service amount=200", "5.00", new BigDecimal("200"));
        assertService("service amount=500", "5.00", new BigDecimal("500"));

        // ===== 服务费：异常流程 =====
        assertThrows("service null amount", () -> FeeCalculator.serviceFee(null));
        assertThrows("service negative amount", () -> FeeCalculator.serviceFee(new BigDecimal("-0.01")));

        // ===== 返回精度与输入不可变 =====
        BigDecimal input = new BigDecimal("200.005");
        BigDecimal before = input;
        BigDecimal result = FeeCalculator.deliveryFee(input, 1);
        assertTrue("input not modified (same reference)", input == before);
        assertTrue("input value unchanged", input.compareTo(new BigDecimal("200.005")) == 0);
        assertTrue("result scale is 2", result.scale() == 2);

        BigDecimal serviceInput = new BigDecimal("100.005");
        BigDecimal serviceBefore = serviceInput;
        BigDecimal serviceResult = FeeCalculator.serviceFee(serviceInput);
        assertTrue("service input not modified (same reference)", serviceInput == serviceBefore);
        assertTrue("service input value unchanged", serviceInput.compareTo(new BigDecimal("100.005")) == 0);
        assertTrue("service result scale is 2", serviceResult.scale() == 2);

        // ===== 汇总 =====
        System.out.println("通过: " + passed + "，失败: " + failed);
        if (failed > 0) {
            throw new AssertionError("存在失败用例: " + failed);
        }
        System.out.println("全部测试通过");
    }

    // ---------- 断言辅助方法 ----------

    private static void assertDelivery(String name, String expected, BigDecimal amount, int itemCount) {
        try {
            BigDecimal actual = FeeCalculator.deliveryFee(amount, itemCount);
            assertEquals(name, new BigDecimal(expected), actual);
        } catch (Exception e) {
            failed++;
            System.out.println("[FAIL] " + name + " 抛出异常: " + e);
        }
    }

    private static void assertService(String name, String expected, BigDecimal amount) {
        try {
            BigDecimal actual = FeeCalculator.serviceFee(amount);
            assertEquals(name, new BigDecimal(expected), actual);
        } catch (Exception e) {
            failed++;
            System.out.println("[FAIL] " + name + " 抛出异常: " + e);
        }
    }

    private static void assertEquals(String name, BigDecimal expected, BigDecimal actual) {
        if (expected.compareTo(actual) == 0 && expected.scale() == actual.scale()) {
            passed++;
            System.out.println("[PASS] " + name + " => " + actual);
        } else {
            failed++;
            System.out.println("[FAIL] " + name + " 期望 " + expected + "，实际 " + actual);
        }
    }

    private static void assertThrows(String name, Runnable action) {
        try {
            action.run();
            failed++;
            System.out.println("[FAIL] " + name + " 未抛出 IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            passed++;
            System.out.println("[PASS] " + name + " 抛出 IllegalArgumentException: " + e.getMessage());
        } catch (Exception e) {
            failed++;
            System.out.println("[FAIL] " + name + " 抛出非预期异常: " + e);
        }
    }

    private static void assertTrue(String name, boolean condition) {
        if (condition) {
            passed++;
            System.out.println("[PASS] " + name);
        } else {
            failed++;
            System.out.println("[FAIL] " + name);
        }
    }
}
